  const DEFAULTS = { capo: 0, font: 17, speed: 3, inline: true };

  // ---- コードダイアグラム（押さえ方の図。データは chord-data.js の ChordDB） ----
  const DB_BASS = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'Bb', 'B'];
